16	+enum AgentQuotaWindowKind: Equatable, Sendable {
17	+  case fiveHour
18	+  case weekly
19	+  case duration(minutes: Int)
20	+
21	+  var compactLabel: String {
22	+    switch self {
23	+    case .fiveHour: return "5h"
24	+    case .weekly: return "wk"
25	+    case .duration(let minutes):
26	+      if minutes.isMultiple(of: 1440) { return "\(minutes / 1440)d" }
27	+      if minutes.isMultiple(of: 60) { return "\(minutes / 60)h" }
28	+      return "\(minutes)m"
29	+    }
30	+  }
31	+}
