33	+struct AgentPace: Equatable, Sendable {
34	+  /// Percentage points ahead of sustainable use. Negative means under pace.
35	+  let percentagePoints: Double
36	+
37	+  var roundedPoints: Int { Int(percentagePoints.rounded()) }
38	+  var isOver: Bool { roundedPoints > 0 }
39	+
40	+  var compactDescription: String {
41	+    if roundedPoints == 0 { return "0%" }
42	+    return "\(roundedPoints > 0 ? "+" : "−")\(abs(roundedPoints))%"
43	+  }
44	+
45	+  var accessibilityDescription: String {
46	+    if roundedPoints == 0 { return "on sustainable pace" }
47	+    if roundedPoints > 0 { return "\(roundedPoints)% in deficit" }
48	+    return "\(abs(roundedPoints))% in reserve"
49	+  }
50	+}
