52	+struct AgentQuotaWindow: Equatable, Sendable, Identifiable {
53	+  let kind: AgentQuotaWindowKind
54	+  let usedPercentage: Double
55	+  let duration: TimeInterval
56	+  let resetsAt: Date
57	+
58	+  var id: String { kind.compactLabel }
59	+
60	+  init(
61	+    kind: AgentQuotaWindowKind, usedPercentage: Double, duration: TimeInterval, resetsAt: Date
62	+  ) {
63	+    self.kind = kind
64	+    self.usedPercentage = min(max(usedPercentage, 0), 100)
65	+    self.duration = duration
66	+    self.resetsAt = resetsAt
67	+  }
68	+
69	+  func pace(at now: Date) -> AgentPace {
70	+    guard duration > 0 else { return AgentPace(percentagePoints: usedPercentage) }
71	+    let startsAt = resetsAt.addingTimeInterval(-duration)
72	+    let elapsed = min(max(now.timeIntervalSince(startsAt) / duration, 0), 1) * 100
73	+    return AgentPace(percentagePoints: usedPercentage - elapsed)
74	+  }
75	+
76	+  func isFresh(at now: Date) -> Bool { now < resetsAt }
77	+
78	+  func resetDescription(at now: Date) -> String {
79	+    let remaining = resetsAt.timeIntervalSince(now)
80	+    guard remaining > 0 else { return "resets now" }
81	+
82	+    // Round up so a still-fresh window never claims to reset in 0m. The footer deliberately stops at
83	+    // minutes: second-level precision adds noise and suggests more certainty than provider snapshots
84	+    // offer.
85	+    var minutes = Int(ceil(remaining / 60))
86	+    let days = minutes / (24 * 60)
87	+    minutes %= 24 * 60
88	+    let hours = minutes / 60
89	+    minutes %= 60
90	+
91	+    var parts: [String] = []
92	+    if days > 0 { parts.append("\(days)d") }
93	+    if hours > 0 { parts.append("\(hours)h") }
94	+    if minutes > 0 { parts.append("\(minutes)m") }
95	+    return "resets in " + parts.joined(separator: ", ")
96	+  }
97	+}
