111	+enum AgentTitleRecognition {
112	+  /// Shell integration reports either the actual command line or the provider's own stable title.
113	+  /// Only the first executable token is considered; wrappers and prose containing an agent name are
114	+  /// deliberately rejected.
115	+  static func backend(for title: String?) -> AgentBackend? {
116	+    guard let title else { return nil }
117	+    let trimmed = title.trimmingCharacters(in: .whitespacesAndNewlines)
118	+    guard !trimmed.isEmpty else { return nil }
119	+    switch trimmed.lowercased() {
120	+    case "claude code": return .claude
121	+    case "codex": return .codex
122	+    default: break
123	+    }
124	+
125	+    guard let first = trimmed.split(whereSeparator: \.isWhitespace).first else { return nil }
126	+    let token = String(first).trimmingCharacters(in: CharacterSet(charactersIn: "\"'"))
127	+    // Provider-owned display titles are handled exactly above. Command titles come from the shell
128	+    // and use the real, lower-case executable name; keeping this comparison case-sensitive avoids
129	+    // treating prose such as "Claude Code setup" as a running agent.
130	+    let executable = (token as NSString).lastPathComponent
131	+    switch executable {
132	+    case "claude": return .claude
133	+    case "codex": return .codex
134	+    default: return nil
135	+    }
136	+  }
137	+}
