157	+enum AgentUsageDecoding {
158	+  static let maximumTailBytes = 256 * 1024
159	+
160	+  static func claude(data: Data, capturedAt: Date, now: Date) -> AgentQuotaSnapshot? {
161	+    guard let root = try? JSONSerialization.jsonObject(with: data) as? [String: Any] else {
162	+      return nil
163	+    }
164	+    let limits = (root["rate_limits"] as? [String: Any]) ?? root
165	+    var windows: [AgentQuotaWindow] = []
166	+    if let value = decodeClaudeWindow(
167	+      limits["five_hour"], kind: .fiveHour, duration: 5 * 60 * 60)
168	+    {
169	+      windows.append(value)
170	+    }
171	+    if let value = decodeClaudeWindow(
172	+      limits["seven_day"], kind: .weekly, duration: 7 * 24 * 60 * 60)
173	+    {
174	+      windows.append(value)
175	+    }
176	+    return normalized(.claude, windows: windows, capturedAt: capturedAt, now: now)
177	+  }
178	+
179	+  static func codexRollout(data: Data, fileSize: UInt64, modifiedAt: Date, now: Date)
180	+    -> AgentQuotaSnapshot?
181	+  {
182	+    var bytes = data
183	+    // A bounded tail can begin halfway through a JSONL record. Drop that fragment.
184	+    if fileSize > UInt64(data.count), let newline = bytes.firstIndex(of: 0x0A) {
185	+      bytes.removeSubrange(...newline)
186	+    }
187	+    for rawLine in bytes.split(separator: 0x0A, omittingEmptySubsequences: true).reversed() {
188	+      guard
189	+        let object = try? JSONSerialization.jsonObject(with: Data(rawLine)) as? [String: Any],
190	+        let payload = object["payload"] as? [String: Any],
191	+        payload["type"] as? String == "token_count",
192	+        let limits = payload["rate_limits"] as? [String: Any]
193	+      else { continue }
194	+
195	+      let capturedAt = (object["timestamp"] as? String).flatMap(parseISO8601) ?? modifiedAt
196	+      var windows: [AgentQuotaWindow] = []
197	+      for key in ["primary", "secondary"] {
198	+        guard let value = limits[key] as? [String: Any],
199	+          let minutes = number(value["window_minutes"]).map(Int.init), minutes > 0,
200	+          let used = number(value["used_percent"])
201	+        else { continue }
202	+        let reset: Date?
203	+        if let seconds = number(value["resets_at"]) {
204	+          reset = Date(timeIntervalSince1970: seconds)
205	+        } else if let remaining = number(value["resets_in_seconds"]) {
206	+          reset = capturedAt.addingTimeInterval(remaining)
207	+        } else {
208	+          reset = nil
209	+        }
210	+        guard let reset else { continue }
211	+        windows.append(
212	+          AgentQuotaWindow(
213	+            kind: kind(for: minutes), usedPercentage: used,
214	+            duration: TimeInterval(minutes * 60), resetsAt: reset))
215	+      }
216	+      if let snapshot = normalized(.codex, windows: windows, capturedAt: capturedAt, now: now) {
217	+        return snapshot
218	+      }
219	+    }
220	+    return nil
221	+  }
222	+
223	+  static func readCodexSnapshot(
224	+    sessionsRoot: URL, now: Date, maximumTailBytes: Int = maximumTailBytes,
225	+    fileManager: FileManager = .default
226	+  ) -> AgentQuotaSnapshot? {
227	+    guard
228	+      let enumerator = fileManager.enumerator(
229	+        at: sessionsRoot,
230	+        includingPropertiesForKeys: [.isRegularFileKey, .contentModificationDateKey],
231	+        options: [.skipsHiddenFiles, .skipsPackageDescendants])
232	+    else { return nil }
233	+    var candidates: [(URL, Date)] = []
234	+    for case let url as URL in enumerator where url.pathExtension == "jsonl" {
235	+      guard
236	+        let values = try? url.resourceValues(forKeys: [
237	+          .isRegularFileKey, .contentModificationDateKey,
238	+        ]),
239	+        values.isRegularFile == true
240	+      else { continue }
241	+      candidates.append((url, values.contentModificationDate ?? .distantPast))
242	+    }
243	+    // A malformed/partially-written newest rollout must not suppress a slightly older valid one.
244	+    for (url, modifiedAt) in candidates.sorted(by: { $0.1 > $1.1 }).prefix(12) {
245	+      guard let handle = try? FileHandle(forReadingFrom: url) else { continue }
246	+      defer { try? handle.close() }
247	+      let size = (try? handle.seekToEnd()) ?? 0
248	+      let count = min(UInt64(maximumTailBytes), size)
249	+      try? handle.seek(toOffset: size - count)
250	+      guard let data = try? handle.read(upToCount: Int(count)), !data.isEmpty else { continue }
251	+      if let snapshot = codexRollout(
252	+        data: data, fileSize: size, modifiedAt: modifiedAt, now: now)
253	+      {
254	+        return snapshot
255	+      }
256	+    }
257	+    return nil
258	+  }
259	+
260	+  private static func decodeClaudeWindow(
261	+    _ raw: Any?, kind: AgentQuotaWindowKind, duration: TimeInterval
262	+  ) -> AgentQuotaWindow? {
263	+    guard let value = raw as? [String: Any],
264	+      let used = number(value["used_percentage"]),
265	+      let reset = number(value["resets_at"])
266	+    else { return nil }
267	+    return AgentQuotaWindow(
268	+      kind: kind, usedPercentage: used, duration: duration,
269	+      resetsAt: Date(timeIntervalSince1970: reset))
270	+  }
271	+
272	+  private static func normalized(
273	+    _ backend: AgentBackend, windows: [AgentQuotaWindow], capturedAt: Date, now: Date
274	+  ) -> AgentQuotaSnapshot? {
275	+    let fresh = windows.filter { $0.isFresh(at: now) }.sorted { $0.duration < $1.duration }
276	+    guard !fresh.isEmpty else { return nil }
277	+    return AgentQuotaSnapshot(backend: backend, windows: fresh, capturedAt: capturedAt)
278	+  }
279	+
280	+  private static func kind(for minutes: Int) -> AgentQuotaWindowKind {
281	+    switch minutes {
282	+    case 300: return .fiveHour
283	+    case 10080: return .weekly
284	+    default: return .duration(minutes: minutes)
285	+    }
286	+  }
287	+
288	+  private static func number(_ value: Any?) -> Double? {
289	+    switch value {
290	+    case let value as NSNumber: return value.doubleValue
291	+    case let value as String: return Double(value)
292	+    default: return nil
293	+    }
294	+  }
295	+
296	+  private static func parseISO8601(_ value: String) -> Date? {
297	+    let formatter = ISO8601DateFormatter()
298	+    formatter.formatOptions = [.withInternetDateTime, .withFractionalSeconds]
299	+    return formatter.date(from: value) ?? ISO8601DateFormatter().date(from: value)
300	+  }
301	+}
