304	+final class AgentUsageMonitor: ObservableObject {
305	+  @Published private(set) var snapshots: [AgentBackend: AgentQuotaSnapshot] = [:]
306	+  @Published private(set) var loading: Set<AgentBackend> = []
307	+
308	+  let codexSessionsURL: URL
309	+  let claudeCacheURL: URL
