315	+
316	+  init(
317	+    codexSessionsURL: URL = FileManager.default.homeDirectoryForCurrentUser
318	+      .appendingPathComponent(".codex/sessions", isDirectory: true),
319	+    claudeCacheURL: URL = ClaudeUsageBridge.defaultDirectory
320	+      .appendingPathComponent("claude-rate-limits.json"),
321	+    now: @escaping () -> Date = Date.init, startAutomatically: Bool = true
322	+  ) {
323	+    self.codexSessionsURL = codexSessionsURL
324	+    self.claudeCacheURL = claudeCacheURL
