347	+  func refresh() {
348	+    // A seeded agent title is a model-only UI fixture. Never replace its deterministic snapshot
349	+    // (including the intentional unavailable case) by reading the developer's real provider files.
350	+    guard UITestFixture.usageAgentTitle == nil else {
351	+      loading.removeAll()
352	+      return
353	+    }
354	+    refreshTask?.cancel()
355	+    loading = Set(AgentBackend.allCases)
356	+    let codexURL = codexSessionsURL
357	+    let claudeURL = claudeCacheURL
358	+    let current = now()
359	+    refreshTask = Task.detached(priority: .utility) {
360	+      let codex = AgentUsageDecoding.readCodexSnapshot(sessionsRoot: codexURL, now: current)
361	+      let claude: AgentQuotaSnapshot? = {
362	+        guard let data = try? Data(contentsOf: claudeURL),
363	+          let attrs = try? FileManager.default.attributesOfItem(atPath: claudeURL.path),
364	+          let modified = attrs[.modificationDate] as? Date
365	+        else { return nil }
366	+        return AgentUsageDecoding.claude(data: data, capturedAt: modified, now: current)
367	+      }()
368	+      guard !Task.isCancelled else { return }
369	+      await MainActor.run {
370	+        self.snapshots = Dictionary(
371	+          uniqueKeysWithValues: [codex, claude].compactMap { $0 }.map { ($0.backend, $0) })
372	+        self.loading.removeAll()
373	+        self.rebuildWatches()
374	+      }
375	+    }
