380	+  private func rebuildWatches() {
381	+    for watch in watches { watch.cancel() }
382	+    watches.removeAll()
383	+    watchedDescriptors.removeAll()
384	+    var paths = [codexSessionsURL, claudeCacheURL.deletingLastPathComponent()]
385	+    if let enumerator = FileManager.default.enumerator(
386	+      at: codexSessionsURL, includingPropertiesForKeys: [.isDirectoryKey],
387	+      options: [.skipsHiddenFiles, .skipsPackageDescendants])
388	+    {
389	+      for case let url as URL in enumerator {
390	+        if (try? url.resourceValues(forKeys: [.isDirectoryKey]).isDirectory) == true {
391	+          paths.append(url)
392	+        }
393	+      }
394	+    }
395	+    for url in paths where FileManager.default.fileExists(atPath: url.path) {
396	+      let descriptor = open(url.path, O_EVTONLY)
397	+      guard descriptor >= 0 else { continue }
398	+      let source = DispatchSource.makeFileSystemObjectSource(
399	+        fileDescriptor: descriptor, eventMask: [.write, .extend, .attrib, .rename, .delete],
400	+        queue: .main)
401	+      source.setEventHandler { [weak self] in self?.scheduleRefresh() }
402	+      source.setCancelHandler { close(descriptor) }
403	+      source.resume()
404	+      watches.append(source)
405	+      watchedDescriptors.append(descriptor)
406	+    }
407	+  }
