409	+  private func scheduleRefresh() {
410	+    debounce?.cancel()
411	+    let item = DispatchWorkItem { [weak self] in self?.refresh() }
412	+    debounce = item
413	+    DispatchQueue.main.asyncAfter(deadline: .now() + 0.25, execute: item)
414	+  }
415	+}
