654	+      withJSONObject: object, options: [.prettyPrinted, .sortedKeys])
655	+    try writer(data, url, permissions)
656	+  }
657	+
658	+  private func settingsPermissions() -> Int {
659	+    let attributes = try? fileManager.attributesOfItem(atPath: settingsURL.path)
