665	+      let left = try? JSONSerialization.data(withJSONObject: [lhs], options: [.sortedKeys]),
666	+      let right = try? JSONSerialization.data(withJSONObject: [rhs], options: [.sortedKeys])
667	+    else { return false }
668	+    return left == right
